DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.operation_action(uuid,text,jsonb)'::regprocedure) INTO def; def:=replace(def,'FROM public.operation_documents d WHERE d.operation_id=o.id AND d.kind=k AND (d.path IS NOT NULL OR d.waiver_approved_by IS NOT NULL)','FROM public.operation_documents od WHERE od.operation_id=o.id AND od.kind=k AND (od.path IS NOT NULL OR od.waiver_approved_by IS NOT NULL)'); EXECUTE def; END $$;